SELECT clock_timestamp() AS db_at,o.external_order_id,l.id,l.fbs_order_id,l.product_id,l.storage_location_id,l.source_warehouse_id,l.source_mode,l.quantity,l.shortage_quantity,l.negative_quantity,l.ozon_positions_json,l.shipment_movement_id,l.written_off_at,l.reversed_at,l.reversal_movement_id,l.created_at FROM fbs_orders o JOIN fbs_shipment_reversal_ledger l ON l.fbs_order_id=o.id AND l.tenant_id=o.tenant_id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon' ORDER BY o.external_order_id LIMIT 80
